import { ulkeleriGetir, ulkeAdi, TURKIYE } from './bolge'

/**
 * `bolgeMetni` KALDIRILDI (kullanicinin karari 2026-09-18 aksam): bolge
 * hicbir profilde gosterilmiyor, yalnizca hesap olusturmada seciliyor.
