describe('ulkeleriGetir', () => {
  it('Turkiye listenin basinda, kalanlar alfabetik', () => {
    const liste = ulkeleriGetir('tr')
    expect(liste[0].kod).toBe(TURKIYE)
    const kalan = liste.slice(1).map((u) => u.ad)
