      <Circle cx={17} cy={17} r={4} fill="none" stroke={renk.turuncu} strokeWidth={1.8} />
      <Line x1={14.2} y1={14.2} x2={19.8} y2={19.8} stroke={renk.turuncu} strokeWidth={1.8} strokeLinecap="round" />
