const testDil = process.env.SLOOIN_TEST_DIL
if (testDil) {
  await sayfa.setExtraHTTPHeaders({ 'Accept-Language': testDil })
  await sayfa.evaluateOnNewDocument((d) => {
    Object.defineProperty(navigator, 'language', { get: () => d })
    Object.defineProperty(navigator, 'languages', { get: () => [d] })
  }, testDil)
}
await sayfa.setGeolocation({
  latitude: Number(process.env.SLOOIN_TEST_LAT ?? 40.2261),
  longitude: Number(process.env.SLOOIN_TEST_LNG ?? 28.8656),
})
await sayfa.setViewport({
  width: Number(gen),
  height: Number(yuk),
  deviceScaleFactor: 2,
  isMobile: true,
  hasTouch: true,
})
// Ic ekranlar oturum istiyor. SLOOIN_TEST_EPOSTA ve SLOOIN_TEST_SIFRE
// tanimliysa once giris yapiliyor; yoksa dogrudan istenen yola
// gidiliyor (giris/kayit gibi acik ekranlar icin). Kimlik e-postaya
// tasindigi icin (2026-09-01/02) giris ekranindaki ilk alan artik
// e-posta - SLOOIN_TEST_TELEFON eski adiyla geriye donuk uyumluluk
// icin hala okunuyor.
const tel = process.env.SLOOIN_TEST_EPOSTA ?? process.env.SLOOIN_TEST_TELEFON
const sif = process.env.SLOOIN_TEST_SIFRE
if (tel && sif) {
  await sayfa.goto(`${tabanAdres}/giris`, {
    waitUntil: 'networkidle0',
    timeout: 60000,
  })
  await sayfa.evaluate(() => document.fonts.ready)
  const alanlar = await sayfa.$$('input')
  if (alanlar.length >= 2) {
